#pragma once
// Embedded logo pixels (generated by scripts/embed_icons.py): lossless QOI-compressed straight-alpha RGBA.
#include <stddef.h>
#include <stdint.h>

typedef struct ccord_icon_image {
  int size;
  const uint8_t *qoi;
  size_t qoi_len;
} ccord_icon_image;

extern const ccord_icon_image ccord_app_icon_images[];   // ascending size: 16, 32, 48, 64, 128, 256
extern const size_t ccord_app_icon_image_count;
extern const ccord_icon_image ccord_tray_icon_images[];  // 22, 24, 32, 48
extern const size_t ccord_tray_icon_image_count;
